package app;
import java.time.*;
import java.util.*;
class Module3 {
 static void menu(){while(true){Data.expire();System.out.println("\n--- MODULE 3: BOOKINGS ---\n1 Register guest\n2 Book rooms\n3 View bookings\n4 Check in\n5 Check out\n6 Change dates\n0 Back");int c=Data.number("Choice: ");if(c==0)return;if(c==1)register();else if(c==2)book();else if(c==3)view();else if(c==4)checkin();else if(c==5)checkout();else if(c==6)change();}}
 static void register(){String n=Data.ask("Name: "),p=Data.ask("Phone: "),e=Data.ask("Email: "),t=Data.ask("ID proof type: "),no=Data.ask("ID proof number: ");if(n.isEmpty()||p.isEmpty()||e.isEmpty()||!e.contains("@")||t.isEmpty()||no.isEmpty()){System.out.println("All valid details required.");return;}Guest g=new Guest(Data.guestId++,n,p,e,t,no);Data.guests.add(g);System.out.println("Guest ID: "+g.id);}
 static void book(){Guest g=Data.guest(Data.number("Guest ID: "));if(g==null){System.out.println("Register first.");return;}int hotelId=Data.number("Hotel ID: ");if(Data.hotel(hotelId)==null)return;LocalDate in=Data.date("Check-in"),out=Data.date("Check-out");if(!Data.validDates(in,out)){System.out.println("Invalid stay dates (1-15 nights, no past date).");return;}int n=Data.number("How many rooms (1-3): ");if(n<1||n>3){System.out.println("Maximum 3 rooms.");return;}ArrayList<Integer> ids=new ArrayList<>();for(int i=0;i<n;i++){int id=Data.number("Room ID: ");Room r=Data.room(id);if(r==null||r.hotelId!=hotelId||ids.contains(id)||Data.blocked(r,in,out,-1)){System.out.println("Invalid/unavailable room. Booking not created.");return;}ids.add(id);}Booking b=new Booking(Data.bookingId++,g.id,hotelId,ids,in,out);b.total=Module4.total(b);Data.bookings.add(b);System.out.println("Booking ID "+b.id+" | Pending Payment | Hold 15 minutes | Total Rs "+b.total);}
 static void view(){for(Booking b:Data.bookings)System.out.println("Booking "+b.id+" Guest "+b.guestId+" Hotel "+b.hotelId+" Rooms "+b.roomIds+" "+b.in+" to "+b.out+" | "+b.status+" | Rs "+b.total);}
 static void checkin(){Booking b=Data.booking(Data.number("Booking ID: "));if(b==null||!b.status.equals("Confirmed")||!LocalDate.now().equals(b.in)){System.out.println("Check-in only on check-in date for confirmed bookings.");return;}Guest g=Data.guest(b.guestId);String id=Data.ask("Verify guest ID proof number: ");if(g!=null&&g.idNumber.equals(id)){b.status="Checked In";System.out.println("Checked in.");}else System.out.println("ID verification failed.");}
 static void checkout(){Booking b=Data.booking(Data.number("Booking ID: "));if(b!=null&&b.status.equals("Checked In")){b.status="Checked Out";System.out.println("Checked out. Room released.");}else System.out.println("Not checked in.");}
 static void change(){Booking b=Data.booking(Data.number("Booking ID: "));if(b==null||!b.status.equals("Confirmed")){System.out.println("Only confirmed bookings.");return;}if(!LocalDateTime.now().isBefore(b.in.atTime(14,0).minusHours(48))){System.out.println("Must request more than 48 hours before check-in.");return;}LocalDate a=Data.date("New check-in"),z=Data.date("New check-out");if(!Data.validDates(a,z)){System.out.println("Invalid dates.");return;}for(int id:b.roomIds)if(Data.blocked(Data.room(id),a,z,b.id)){System.out.println("Room unavailable on new dates.");return;}b.in=a;b.out=z;b.total=Module4.total(b);System.out.println("Dates changed. Updated price Rs "+b.total+"; coordinate any payment difference.");}
}
